    register_taxonomy('categorias-evento', 'eventos', array(
        'labels' => array(
            'name'          => 'Categorías de Evento',
            'singular_name' => 'Categoría de Evento',
            'search_items'  => 'Buscar categorías',
            'all_items'     => 'Todas las categorías',
            'parent_item'   => 'Categoría padre',
            'edit_item'     => 'Editar categoría',
            'update_item'   => 'Actualizar categoría',
            'add_new_item'  => 'Añadir nueva categoría',
            'new_item_name' => 'Nombre de nueva categoría',
        ),
        'hierarchical'      => true,
        'show_ui'           => true,
        'show_admin_column' => true,
        'query_var'         => true,
        'rewrite'           => array('slug' => 'categoria-evento'),
    ));

    // Limpieza de reglas de reescritura al activar para actualizar slugs correctamente
    flush_rewrite_rules();
}
add_action('init', 'eventos_register_cpt_taxonomy');

