function eventos_render_meta_box($post) {
    wp_nonce_field('eventos_save_data', 'eventos_nonce');

    $fecha = get_post_meta($post->ID, '_evento_fecha', true);
    $lugar = get_post_meta($post->ID, '_evento_lugar', true);
    $precio = get_post_meta($post->ID, '_evento_precio', true);

    ?>
    <div class="eventos-meta-box-wrap">
        <p>
            <label for="_evento_fecha"><strong>Fecha del evento:</strong></label><br>
            <input type="date" id="_evento_fecha" name="_evento_fecha" value="<?php echo esc_attr($fecha); ?>" style="width: 100%;">
        </p>
        <p>
            <label for="_evento_lugar"><strong>Lugar:</strong></label><br>
            <input type="text" id="_evento_lugar" name="_evento_lugar" value="<?php echo esc_attr($lugar); ?>" style="width: 100%;" placeholder="Ej: Centro de Convenciones">
        </p>
        <p>
            <label for="_evento_precio"><strong>Precio (€):</strong></label><br>
            <input type="number" step="0.01" min="0" id="_evento_precio" name="_evento_precio" value="<?php echo esc_attr($precio); ?>" style="width: 100%;" placeholder="0.00">
        </p>
    </div>
    <?php
}

function eventos_save_meta_box($post_id) {
    // Verificar nonce
    if (!isset($_POST['eventos_nonce']) || !wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['eventos_nonce'])), 'eventos_save_data')) {
        return;
    }

    // Verificar autosave y capacidades
    if (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE) return;
    if (!current_user_can('edit_post', $post_id)) return;

    // Sanitizar y guardar meta datos
    $fecha = sanitize_text_field(wp_unslash($_POST['_evento_fecha']));
    $lugar = sanitize_text_field(wp_unslash($_POST['_evento_lugar']));
    $precio = absint(wp_unslash($_POST['_evento_precio']));

    update_post_meta($post_id, '_evento_fecha', $fecha);
    update_post_meta($post_id, '_evento_lugar', $lugar);
    update_post_meta($post_id, '_evento_precio', $precio);
}
add_action('save_post_eventos', 'eventos_save_meta_box');

