class Eventos_Admin_List_Table extends WP_List_Table {

    public function __construct() {
        parent::__construct(array(
            'singular' => 'evento',
            'plural'   => 'eventos',
            'ajax'     => false,
        ));
    }

    public function get_columns() {
        return array(
            'cb'         => '<input type="checkbox" />',
            'titulo'     => __('Título', 'eventos-pro'),
            'categoria'  => __('Categoría', 'eventos-pro'),
            'fecha'      => __('Fecha', 'eventos-pro'),
            'lugar'      => __('Lugar', 'eventos-pro'),
            'precio'     => __('Precio (€)', 'eventos-pro'),
            'acciones'   => __('Acciones', 'eventos-pro'),
        );
    }

    public function prepare_items() {
        $per_page = 10;
        $current_page = $this->get_pagenum();
        $offset = ($current_page - 1) * $per_page;

        // Búsqueda
        $search = !empty($_GET['s']) ? sanitize_text_field(wp_unslash($_GET['s'])) : '';

        // Query de conteo total (sin paginación)
        $count_query = new WP_Query(array(
            'post_type'   => 'eventos',
            'post_status' => array('publish', 'draft'),
            'fields'      => 'ids',
            's'           => $search,
        ));
        $total_items = count($count_query->posts);

        // Query principal con paginación y orden por fecha
        $args = array(
            'post_type'      => 'eventos',
            'post_status'    => array('publish', 'draft'),
            'posts_per_page' => $per_page,
            'offset'         => $offset,
            'orderby'        => 'meta_value',
            'meta_key'       => '_evento_fecha',
            'order'          => 'ASC',
            's'              => $search,
        );

        $query = new WP_Query($args);
        $this->items = array();

        if ($query->have_posts()) {
            foreach ($query->posts as $post) {
                $fecha = get_post_meta($post->ID, '_evento_fecha', true);
                $lugar = get_post_meta($post->ID, '_evento_lugar', true);
                $precio_raw = get_post_meta($post->ID, '_evento_precio', true);
                $precio = !empty($precio_raw) ? number_format((float)$precio_raw, 2) : '-';

                $terms = wp_get_post_terms($post->ID, 'categorias-evento', array('fields' => 'names'));
                $categoria_str = !empty($terms) ? implode(', ', array_map('esc_html', $terms)) : '-';

                $this->items[] = array(
                    'cb'         => '<input type="checkbox" name="eventos_bulk[]" value="' . esc_attr($post->ID) . '" />',
                    'titulo'     => '<strong>' . esc_html($post->post_title) . '</strong>',
                    'categoria'  => $categoria_str,
                    'fecha'      => esc_html($fecha),
                    'lugar'      => esc_html($lugar),
                    'precio'     => esc_html($precio),
                    'acciones'   => sprintf(
                        '<a href="%s">%s</a> | <a href="%s" class="delete-evento-row">%s</a>',
                        esc_url(get_edit_post_link($post->ID)),
                        __('Editar', 'eventos-pro'),
                        esc_url(get_delete_post_link($post->ID)),
                        __('Eliminar', 'eventos-pro')
                    ),
                );
            }
        }

        // Configurar paginación para WP_List_Table
        $this->set_pagination_args(array(
            'total_items' => $total_items,
            'per_page'    => $per_page,
        ));
    }

    public function column_default($item, $column_name) {
        return $item[$column_name];
    }

    public function no_items() {
        _e('No hay eventos registrados.', 'eventos-pro');
    }

    // Renderizado seguro de acciones (previene XSS)
    public function column_acciones($item) {
        echo $item['acciones']; // Ya está escapado en prepare_items
    }

    public function get_sortable_columns() {
        return array(
            'titulo'  => array('titulo', false),
            'fecha'   => array('_evento_fecha', true), // ASC por defecto
            'precio'  => array('_evento_precio', true),
        );
    }

    // Interceptamos ordenamiento personalizado si fuera necesario, pero WP_List_Table ya lo maneja con meta_key/orderby
}

function eventos_render_admin_table() {
    if (!current_user_can('manage_options')) {
        wp_die(__('No tienes permisos para acceder a esta página.', 'eventos-pro'));
    }

    $table = new Eventos_Admin_List_Table();
    $table->prepare_items();
    ?>
    <div class="wrap">
        <h1><?php echo esc_html(get_admin_page_title()); ?></h1>
        <?php $table->display(); ?>
    </div>
    <?php
}

