// 4. SHORTCODE [eventos_proximos]
// ==========================================
function eventos_shortcode_proximos($atts) {
    extract(shortcode_atts(array(
        'limit'   => 5,
        'orderby' => 'meta_value',
        'order'   => 'ASC',
        'category' => '',
    ), $atts));

    // Obtener fecha actual de WordPress (respeta zona horaria del sitio)
    $today = current_time('Y-m-d');

    $args = array(
        'post_type'      => 'eventos',
        'posts_per_page' => absint($limit),
        'paged'          => get_query_var('paged', 1), // Crucial para paginación en queries custom
        'meta_key'       => '_evento_fecha',
        'orderby'        => $orderby,
        'order'          => sanitize_text_field(wp_unslash($order)),
        'meta_query'     => array(
            array(
                'key'     => '_evento_fecha',
                'value'   => $today,
                'compare' => '>=',
                'type'    => 'DATE',
            ),
        ),
    );

    if (!empty($category)) {
        $terms = array_map('sanitize_text_field', explode(',', wp_unslash($category)));
        $args['tax_query'] = array(
            array(
                'taxonomy' => 'categorias-evento',
                'field'    => 'slug',
                'terms'    => $terms,
            ),
        );
    }

    $query = new WP_Query($args);

    if (!$query->have_posts()) {
        return '<div class="eventos-empty">' . __('No hay eventos próximos disponibles.', 'eventos-pro') . '</div>';
    }

    ob_start(); ?>
    <div class="eventos-proximos-container">
        <ul class="eventos-grid">
            <?php while ($query->have_posts()) : $query->the_post(); 
                $fecha = get_post_meta(get_the_ID(), '_evento_fecha', true);
                $lugar = get_post_meta(get_the_ID(), '_evento_lugar', true);
                $precio_raw = get_post_meta(get_the_ID(), '_evento_precio', true);
                $precio = !empty($precio_raw) ? number_format((float)$precio_raw, 2) . ' €' : __('Gratis', 'eventos-pro');
            ?>
                <li class="evento-card">
                    <h3 class="evento-titulo"><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3>
                    <div class="evento-meta">
                        <span class="evento-fecha"><strong><?php _e('Fecha:', 'eventos-pro'); ?></strong> <?php echo esc_html($fecha); ?></span>
                        <span class="evento-lugar"><strong><?php _e('Lugar:', 'eventos-pro'); ?></strong> <?php echo esc_html($lugar); ?></span>
                        <span class="evento-precio"><strong><?php _e('Precio:', 'eventos-pro'); ?></strong> <?php echo esc_html($precio); ?></span>
                    </div>
                    <div class="evento-excerpt"><?php the_excerpt(); ?></div>
                    <a href="<?php the_permalink(); ?>" class="btn-evento"><?php _e('Ver Detalles', 'eventos-pro'); ?></a>
                </li>
            <?php endwhile; wp_reset_postdata(); ?>
        </ul>

        <?php if ($query->max_num_pages > 1) : ?>
            <nav class="eventos-pagination">
                <?php
                echo paginate_links(array(
                    'base'         => str_replace(999999999, '%#%', esc_url(get_pagenum_link(999999999))),
                    'format'       => '?paged=%#%',
                    'current'      => max(1, get_query_var('paged')),
                    'total'        => $query->max_num_pages,
                    'prev_text'    => '&laquo; ' . __('Anterior', 'eventos-pro'),
                    'next_text'    => __('Siguiente', 'eventos-pro') . ' &raquo;',
                    'type'         => 'list',
                    'mid_size'     => 2,
                ));
                ?>
            </nav>
        <?php endif; ?>
    </div>
    <?php return ob_get_clean();
}
add_shortcode('eventos_proximos', 'eventos_shortcode_proximos');

