```php
<?php
/**
 * Plugin Name:  External Product Sync
 * Description:  Sincroniza productos externos vía REST API como CPT 'producto'. Incluye cron automático, retry lógico, parseo JSON, gestión de meta fields y logging estructurado via WP_Error.
 * Version:      1.0.0
 * Author:       AI Assistant
 * License:      GPL-2.0+
 */

if ( ! defined( 'ABSPATH' ) ) {
    exit; // Acceso directo no permitido
}

// Configuración global (sobrescribible en wp-config.php)
if ( ! defined( 'EPS_API_URL' ) ) define( 'EPS_API_URL', 'https://api.ejemplo.com/v1/productos' );
if ( ! defined( 'EPS_SYNC_HOURS' ) ) define( 'EPS_SYNC_HOURS', 6 );
if ( ! defined( 'EPS_MAX_RETRIES' ) ) define( 'EPS_MAX_RETRIES', 3 );
if ( ! defined( 'EPS_TIMEOUT' ) ) define( 'EPS_TIMEOUT', 15 );

/**
 * Clase principal para la sincronización de productos externos.
 * Gestiona hooks, registro de CPT, cron, fetch con retry, persistencia de datos y logging.
 */
class External_Product_Sync {

    /** @var string URL base del endpoint externo */
    private $api_url;

    /** @var int Intervalo de sincronización en horas */
    private $sync_interval_hours;

    /** @var int Número máximo de reintentos */
    private $max_retries;

    /** @var int Timeout en segundos para peticiones remotas */
    private $timeout_seconds;

    /** @var string Prefijo para transients y opciones internas */
    private $transient_prefix;

    /** @var bool Flag para evitar ejecución múltiple por request */
    private $transient_cleanup_run = false;

    /**
     * Constructor: Inicializa propiedades y registra hooks críticos.
     */
    public function __construct() {
        $this->api_url             = EPS_API_URL;
        $this->sync_interval_hours = EPS_SYNC_HOURS;
        $this->max_retries         = EPS_MAX_RETRIES;
        $this->timeout_seconds     = EPS_TIMEOUT;
        $this->transient_prefix    = 'eps_sync_';

        $this->register_hooks();
        $this->schedule_cron_event();
    }

    /**
     * Método estático de inicialización recomendado para plugins.
     * 
     * @return External_Product_Sync Instancia de la clase principal.
     */
    public static function init() {
        return new self();
    }

    /**
     * Registra todos los hooks de WordPress necesarios para el ciclo de vida del plugin.
     * 
     * @return void
     */
    private function register_hooks() {
        add_action( 'init', [ $this, 'register_cpt' ] );
        add_filter( 'cron_schedules', [ $this, 'add_custom_interval' ] );
        add_action( 'eps_sync_products', [ $this, 'trigger_sync' ] );
        add_action( 'wp', [ $this, 'clean_expired_transients' ] );
    }

    /**
     * Registra el Custom Post Type 'producto' con soporte REST y campos personalizados.
     * 
     * @return void
     */
    public function register_cpt() {
        if ( post_type_exists( 'producto' ) ) {
            return;
        }

