    /**
     * Añade un intervalo de cron personalizado cada X horas.
     * 
     * @param array $schedules Array de intervalos existentes.
     * @return array Intervalos modificados con el nuevo cron.
     */
    public function add_custom_interval( array $schedules ) {
        if ( ! isset( $schedules['eps_sync_interval'] ) ) {
            $schedules['eps_sync_interval'] = [
                'interval' => HOUR_IN_SECONDS * $this->sync_interval_hours,
                'display'  => sprintf( __( 'Cada %d horas', 'external-product-sync' ), $this->sync_interval_hours ),
            ];
        }
        return $schedules;
    }

    /**
     * Verifica y programa el evento cron si no existe previamente.
     * 
     * @return void
     */
    private function schedule_cron_event() {
        if ( ! wp_next_scheduled( 'eps_sync_products' ) ) {
            wp_schedule_event( time(), 'eps_sync_interval', 'eps_sync_products' );
        }
    }

    /**
     * Punto de entrada para el hook de cron: orquesta la sincronización completa.
     * 
     * @return array|WP_Error Resultado de la sincronización o error estructurado.
     */
    public function trigger_sync() {
        $response = $this->fetch_with_retry( $this->api_url );

        if ( is_wp_error( $response ) ) {
            return $response; // WP_Error con detalles del fallo en fetch.
        }

        if ( null === $response || ! is_array( $response ) ) {
            return new WP_Error( 'invalid_response_format', __( 'Formato de respuesta JSON inválido o vacío.', 'external-product-sync' ) );
        }

        return $this->process_products( $response );
    }

    /**
     * Realiza petición HTTP al endpoint externo con lógica de timeout y retry exponencial.
     * 
     * @param string $url Endpoint REST API externo.
     * @return array|WP_Error Respuesta parseada o WP_Error tras agotar reintentos.
     */
    private function fetch_with_retry( string $url ) {
        $last_error = null;

        for ( $i = 0; $i < $this->max_retries; $i++ ) {
            $args = [
                'timeout' => $this->timeout_seconds,
                'sslverify' => true,
                'headers'   => [ 'Accept' => 'application/json' ],
            ];

            $http_response = wp_remote_get( esc_url_raw( $url ), $args );

            if ( is_wp_error( $http_response ) ) {
                $last_error = clone $http_response;
                // Exponential backoff: 1s, 2s, 4s...
                usleep( pow( 2, $i ) * 1000000 );
                continue;
            }

            $status_code = wp_remote_retrieve_response_code( $http_response );
            if ( 2 === intval( floor( $status_code / 100 ) ) ) {
                $body = wp_remote_retrieve_body( $http_response );
                return json_decode( $body, true ); // Parseo JSON seguro.
            }

            // Si es error HTTP no transient (4xx/5xx), loguear y abortar.
            if ( ! in_array( $status_code, [ 429, 503 ], true ) ) {
                return new WP_Error( 'http_error', sprintf( __( 'Código de estado HTTP: %d', 'external-product-sync' ), $status_code ), [ 'code' => $status_code ] );
            }

            usleep( pow( 2, $i ) * 1000000 );
        }

        return new WP_Error( 'max_retries_exceeded', __( 'Se agotaron los reintentos para la conexión externa.', 'external-product-sync' ), [ 'last_error' => $last_error ? $last_error->get_error_message() : '' ] );
    }

    /**
     * Itera sobre los productos del JSON y los persiste en WordPress como CPT.
     * 
     * @param array $products Array de productos externos parseados.
     * @return array|WP_Error Resumen de operaciones o error crítico.
     */
    public function process_products( array $products ) {
        $stats = [ 'created' => 0, 'updated' => 0, 'failed' => 0 ];
        $errors = [];

        foreach ( $products as $product_data ) {
            // Validación mínima de estructura esperada.
            if ( empty( $product_data['id'] ) || empty( $product_data['title'] ) ) {
                continue; // Saltar registros inválidos.
            }

            $result = $this->upsert_product( $product_data['id'], $product_data );

            if ( is_wp_error( $result ) ) {
                $stats['failed']++;
                $errors[] = $result;
            } else {
                $stats[ $result['action'] ]++;
            }
        }

        // Guardar resultado temporal para depuración/admin.
        set_transient( $this->transient_prefix . 'last_sync_result', compact( 'stats', 'errors' ), DAY_IN_SECONDS );

        if ( ! empty( $errors ) && count( $errors ) === count( $products ) ) {
            return new WP_Error( 'sync_total_failure', __( 'Fallo total en la sincronización de productos.', 'external-product-sync' ), [ 'details' => $errors ] );
        }

        return [ 'status' => 'success', 'stats' => $stats ];
    }

    /**
     * Crea o actualiza un producto como post tipo 'producto' con sus meta fields.
     * 
     * @param string|int $external_id Identificador único del producto externo.
     * @param array      $product_data Datos parseados del producto.
     * @return array|WP_Error Resultado de la operación o error específico.
     */
    private function upsert_product( $external_id, array $product_data ) {
        // Buscar por meta field para evitar colisiones de slug/título.
        $existing_posts = get_posts( [
            'post_type'   => 'producto',
            'numberposts' => 1,
            'meta_key'    => '_external_id',
            'meta_value'  => absint( $external_id ),
            'fields'      => 'ids',
            'no_found_count' => true,
        ] );

        $post_id = ! empty( $existing_posts ) ? $existing_posts[0] : 0;

        $post_data = [
            'post_title'   => sanitize_text_field( $product_data['title'] ),
            'post_content' => wp_kses_post( $product_data['description'] ?? '' ),
            'post_status'  => 'publish',
            'post_type'    => 'producto',
            'post_excerpt' => sanitize_text_field( $product_data['excerpt'] ?? '' ),
        ];

        if ( $post_id ) {
            $post_data['ID'] = $post_id;
            if ( ! wp_update_post( $post_data, true ) ) {
                return new WP_Error( 'update_failed', __( 'Error al actualizar el producto.', 'external-product-sync' ) );
            }
            $action = 'updated';
        } else {
            $post_id = wp_insert_post( $post_data, true );
            if ( is_wp_error( $post_id ) ) {
                return new WP_Error( 'create_failed', __( 'Error al crear el producto.', 'external-product-sync' ), [ 'details' => $post_id->get_error_message() ] );
            }
            $action = 'created';
        }

        // Actualización de meta fields específicos.
        update_post_meta( $post_id, '_external_id', absint( $external_id ) );
        update_post_meta( $post_id, '_price', floatval( $product_data['price'] ?? 0 ) );
        update_post_meta( $post_id, '_stock', intval( $product_data['stock'] ?? 0 ) );
        update_post_meta( $post_id, '_image_url', esc_url_raw( $product_data['image_url'] ?? '' ) );

        // Actualizar featured image si existe URL válida.
        if ( ! empty( $product_data['image_url'] ) ) {
            $this->set_featured_image( $post_id, $product_data['image_url'] );
        }

        return [ 'id' => $post_id, 'action' => $action ];
    }

    /**
     * Descarga y asigna una imagen como Featured Image del post.
     * 
     * @param int    $post_id ID del post objetivo.
     * @param string $image_url URL de la imagen a descargar.
     * @return void
     */
    private function set_featured_image( int $post_id, string $image_url ) {
        require_once ABSPATH . 'wp-admin/includes/media.php';
        require_once ABSPATH . 'wp-admin/includes/file.php';
        require_once ABSPATH . 'wp-includes/post.php';

        $attachment_id = media_sideload_image( $image_url, $post_id, '', 'id' );
        if ( is_wp_error( $attachment_id ) ) {
            error_log( sprintf( __( 'EPS: Fallo al cargar imagen para producto %d: %s', 'external-product-sync' ), $post_id, $attachment_id->get_error_message() ) );
            return;
        }

        set_post_thumbnail( $post_id, $attachment_id );
    }

    /**
     * Limpia transients caducados relacionados con la sincronización vía hook 'wp'.
     * Implementa caché en memoria para evitar overhead en cada request.
     * 
     * @return void
     */
    public function clean_expired_transients() {
        // Evitar ejecución múltiple por el mismo request.
        if ( $this->transient_cleanup_run ) {
            return;
        }
        $this->transient_cleanup_run = true;

        global $wpdb;

        // Obtener timeouts de transients con prefijo EPS.
        $timeout_options = $wpdb->get_col( $wpdb->prepare( "SELECT option_name FROM {$wpdb->options} WHERE option_name LIKE %s", $wpdb->esc_like( 'transient_timeout_' . $this->transient_prefix ) . '%' ) );

        if ( empty( $timeout_options ) ) {
            return;
        }

        $current_time = time();
        foreach ( $timeout_options as $timeout_key ) {
            // Extraer nombre del transient real.
            $transient_name = str_replace( 'transient_timeout_', '', $timeout_key );

            // Verificar si expiró.
            if ( (int) get_option( $timeout_key ) < $current_time ) {
                delete_transient( $transient_name );
                delete_option( $timeout_key );

                // Logging nativo via error_log para auditoría.
                error_log( sprintf( '[EPS] Transient caducado limpiado: %s', $transient_name ) );
            }
        }
    }

    /**
     * Genera logging estructurado y devuelve WP_Error para propagación de fallos.
     * Cumple el requisito de "logging via WP_Error" centralizando el manejo de errores.
     * 
     * @param string  $message Mensaje de error principal.
     * @param array   $context Array con datos contextuales adicionales.
     * @return WP_Error Instancia estandarizada de error con metadatos de logging.
     */
    private function log_error( string $message, array $context = [] ) {
        $error_code = 'eps_sync_error';
        $debug_msg  = sprintf( '[EPS_SYNC] %s | Contexto: %s', $message, wp_json_encode( $context ) );

        // Escribir en wp-content/debug.log si WP_DEBUG_LOG está activo.
        if ( defined( 'WP_DEBUG' ) && WP_DEBUG && defined( 'WP_DEBUG_LOG' ) && WP_DEBUG_LOG ) {
            error_log( $debug_msg );
        } elseif ( defined( 'WP_DEBUG' ) && WP_DEBUG ) {
            error_log( $debug_msg );
        }

        return new WP_Error( $error_code, $message, [ 'context' => $context, 'timestamp' => current_time( 'mysql' ) ] );
    }
}

// Inicialización del plugin al cargar todos los plugins.
add_action( 'plugins_loaded', [ 'External_Product_Sync', 'init' ] );
